import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.0
    torso_width = 2.0
    torso_height = 0.5
    torso_density = 2.0
    torso = sandbox.add_beam(
        x=start_x, y=start_y, width=torso_width, height=torso_height, angle=0, density=torso_density
    )
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.5)

    # Use large wheels to ensure ground contact while staying within build zone
    wheel_radius = 1.0
    wheel_y = start_y  # Place wheels at y=2.0m to touch the ground at y=1.0m
    wheel1 = sandbox.add_wheel(x=start_x - 1.0, y=wheel_y, radius=wheel_radius, friction=0.8, density=1.0)
    wheel2 = sandbox.add_wheel(x=start_x + 1.0, y=wheel_y, radius=wheel_radius, friction=0.8, density=1.0)

    # Connect wheels to torso with pivot joints
    joint1 = sandbox.add_joint(torso, wheel1, (start_x - 1.0, wheel_y), type='pivot')
    joint2 = sandbox.add_joint(torso, wheel2, (start_x + 1.0, wheel_y), type='pivot')

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None
    if torso is not None and torso.position.x > 28.0:
        rotation_speed = 0.0
    else:
        rotation_speed = -3.0  # Reduced motor speed to avoid joint angle limits
    for j in joints:
        sandbox.set_motor(j, rotation_speed, max_torque=1000.0)
